// Cinematic stability index — record JAH-GAIS-GIMBALCAMERA-000001
// Property of Justin Addam Higgins (JAH). Deterministic: same inputs, same output.
var m = {"sensor_in": 1.0, "tracking_modes": 5, "price_usd": 500};
var value = (m.sensor_in*100*m.tracking_modes/m.price_usd*10);
if (!isFinite(value)) { console.log('DEMO_FAIL|JAH-GAIS-GIMBALCAMERA-000001|non-finite'); process.exit(1); }
console.log('DEMO_OK|JAH-GAIS-GIMBALCAMERA-000001|' + value.toFixed(2) + ' stability index');

